Lemma ncells_split : forall m A c1 c2 c3 c4 c5 c6, rw_cells asegs m A [C8 c1; C8 c2; C4 c3; C4 c4; C4 c5; C4 c6] ->
  rw_cells asegs m A [C8 c1] /\ rw_cells asegs m (A + 8) [C8 c2] /\ rw_cells asegs m (A + 16) [C4 c3]
